 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Identify the divider color from uniform full-width rows.
    sep = next(grid[r][0] for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0)
    row_bands, col_bands = [], []
    r = 0
    while r < h:
        if all(v == sep for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and not all(v == sep for v in grid[r]):
            r += 1
        row_bands.append((start, r))
    c = 0
    while c < w:
        if all(grid[y][c] == sep for y in range(h)):
            c += 1
            continue
        start = c
        while c < w and not all(grid[y][c] == sep for y in range(h)):
            c += 1
        col_bands.append((start, c))
    out = [row[:] for row in grid]
    # The first colored pattern outside the left column is the stencil.
    template = None
    for r0, r1 in row_bands:
        for c0, c1 in col_bands[1:]:
            cells = [(y-r0, x-c0) for y in range(r0, r1) for x in range(c0, c1)
                     if grid[y][x] not in (0, sep)]
            if cells:
                template = cells
                break
        if template:
            break
    if template:
        for r0, r1 in row_bands:
            color = next((grid[y][x] for y in range(r0, r1)
                          for x in range(col_bands[0][0], col_bands[0][1])
                          if grid[y][x] not in (0, sep)), 0)
            for c0, c1 in col_bands:
                for dy, dx in template:
                    out[r0+dy][c0+dx] = color
    return out
